```go
package cart

// Item represents a product in the shopping cart
type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

// ShoppingCart manages items for purchase
type ShoppingCart struct {
	items map[string]*Item
}

// NewShoppingCart creates a new empty cart
func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

// AddItem adds an item to the cart or increases quantity if exists
func (c *ShoppingCart) AddItem(id, name string, price float64, quantity int) {
	if existing, ok := c.items[id]; ok {
		existing.Quantity += quantity
		return
	}
	c.items[id] = &Item{
		ID:       id,
		Name:     name,
		Price:    price,
		Quantity: quantity,
	}
}

// RemoveItem removes an item entirely from the cart
func (c *ShoppingCart) RemoveItem(id string) {
	delete(c.items, id)
}

// UpdateQuantity sets the quantity for an item
func (c *ShoppingCart) UpdateQuantity(id string, quantity int) {
	if item, ok := c.items[id]; ok {
		if quantity <= 0 {
			delete(c.items, id)
			return
		}
		item.Quantity = quantity
	}
}

// GetItem returns an item by ID
func (c *ShoppingCart) GetItem(id string) *Item {
	return c.items[id]
}

// GetItems returns all items in the cart
func (c *ShoppingCart) GetItems() []*Item {
	result := make([]*Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, item)
	}
	return result
}

// GetTotal calculates the total price of all items
func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

// GetItemCount returns the total number of items (sum of quantities)
func (c *ShoppingCart) GetItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

// Clear removes all items from the cart
func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

// IsEmpty returns true if the cart has no items
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
